/**
 * The §10.1 base fixture as literal SQL-function inputs — written out by hand,
 * NOT generated by the engine's buildSchedule, so the SQL suite stands on its
 * own and cannot inherit a scheduling bug.
 *
 * Plan: weekly [Fri], interval 1, anchor 2026-10-02 (Fri), on_anchor, count 3,
 * split_total 60000 → 10-02, 10-09, 10-16 × 20000; America/New_York, 10:00
 * local → due_at 14:00Z (EDT); auto_charge; maxAttempts 3; retryAfterDays 2.
 */
import type { SeededRental } from "./pglite";

export function basePlanJson(r: Pick<SeededRental, "tenantId" | "rentalId" | "customerId">, over: Record<string, unknown> = {}) {
  return {
    tenantId: r.tenantId,
    rentalId: r.rentalId,
    customerId: r.customerId,
    rule: {
      freq: "weekly",
      interval: 1,
      byWeekday: [5],
      anchor: "2026-10-02",
      firstOccurrence: "on_anchor",
      end: { kind: "count", count: 3 },
    },
    amount: { mode: "split_total", totalCents: 60000 },
    currency: "usd",
    timezone: "America/New_York",
    chargeLocalTime: "10:00",
    collectionMethod: "auto_charge",
    fallbackToLink: true,
    maxAttempts: 3,
    retryAfterDays: 2,
    reminderOffsets: [-2, 0, 2],
    paymentProvider: "stripe",
    stripePaymentMethodId: null,
    extendsRental: false,
    ...over,
  };
}

export const BASE_DRAFTS = [
  { seq: 1, dueDate: "2026-10-02", periodStart: "2026-10-02", periodEnd: "2026-10-09", days: 7, amountCents: 20000, isStub: false },
  { seq: 2, dueDate: "2026-10-09", periodStart: "2026-10-09", periodEnd: "2026-10-16", days: 7, amountCents: 20000, isStub: false },
  { seq: 3, dueDate: "2026-10-16", periodStart: "2026-10-16", periodEnd: "2026-10-23", days: 7, amountCents: 20000, isStub: false },
];

/** due_at of each base occurrence: 10:00 America/New_York in EDT = 14:00Z. */
export const BASE_DUE_AT = ["2026-10-02T14:00:00.000Z", "2026-10-09T14:00:00.000Z", "2026-10-16T14:00:00.000Z"];
